export async function getJoinInstructionAsync<
  TAccountWallet extends string,
  TAccountPayer extends string,
  TAccountLibrary extends string,
  TAccountMember extends string,
  TAccountSystemProgram extends string,
  TProgramAddress extends Address = typeof SEED_LIBRARY_PROGRAM_ADDRESS,
>(
  input: JoinAsyncInput<
    TAccountWallet,
    TAccountPayer,
    TAccountLibrary,
    TAccountMember,
    TAccountSystemProgram
  >,
  config?: { programAddress?: TProgramAddress },
): Promise<
  JoinInstruction<
    TProgramAddress,
    TAccountWallet,
    TAccountPayer,
    TAccountLibrary,
    TAccountMember,
    TAccountSystemProgram
  >
> {
  // Program address.
  const programAddress = config?.programAddress ?? SEED_LIBRARY_PROGRAM_ADDRESS;

  // Original accounts.
  const originalAccounts = {
    wallet: { value: input.wallet ?? null, isWritable: false },
    payer: { value: input.payer ?? null, isWritable: true },
    library: { value: input.library ?? null, isWritable: true },
    member: { value: input.member ?? null, isWritable: true },
    systemProgram: { value: input.systemProgram ?? null, isWritable: false },
  };
  const accounts = originalAccounts as Record<
    keyof typeof originalAccounts,
    ResolvedAccount
  >;

  // Resolve default values.
  if (!accounts.member.value) {
    accounts.member.value = await findMemberPda({
      library: expectAddress(accounts.library.value),
      wallet: expectAddress(accounts.wallet.value),
    });
  }
  if (!accounts.systemProgram.value) {
    accounts.systemProgram.value =
      "11111111111111111111111111111111" as Address<"11111111111111111111111111111111">;
  }

  const getAccountMeta = getAccountMetaFactory(programAddress, "programId");
  return Object.freeze({
    accounts: [
      getAccountMeta(accounts.wallet),
      getAccountMeta(accounts.payer),
      getAccountMeta(accounts.library),
      getAccountMeta(accounts.member),
      getAccountMeta(accounts.systemProgram),
    ],
    data: getJoinInstructionDataEncoder().encode({}),
    programAddress,
  } as JoinInstruction<
    TProgramAddress,
    TAccountWallet,
    TAccountPayer,
    TAccountLibrary,
    TAccountMember,
    TAccountSystemProgram
  >);
}

